    "countryOfOrigin": "Japan",
    "colour": "Dark brown",
    "grainSize": "2 to 5 mm",
    "phTarget": "6.2 to 6.8",
    "phEffect": "lowers-gentle",
    "khEffect": "lowers-gentle",
    "ammoniaRelease": "light",
    "nutrientContent": "High",
    "bufferingLongevity": "12 to 18 months",
